from django.utils import timezone


def preencher_data_atendimento(apps, schema_editor):
    """Registros já existentes: data do atendimento = do agendamento vinculado, senão o dia
    em que foram digitados. Sem isso o '-data_atendimento' (nulos primeiro no PostgreSQL)
    bagunçaria a ordem do prontuário."""
    EntradaProntuario = apps.get_model("prontuario", "EntradaProntuario")
    for entrada in EntradaProntuario.objects.filter(data_atendimento__isnull=True).select_related("agendamento"):
        momento = entrada.agendamento.data_hora_inicio if entrada.agendamento_id else entrada.criado_em
        EntradaProntuario.objects.filter(pk=entrada.pk).update(data_atendimento=timezone.localdate(momento))


